{
  "meta": {
    "name": "CRM",
    "description": "A CRM application with user authentication, contact management, a dashboard, role-based access for admins and members, and a premium plan with payment processing and analytics for admins.",
    "version": "1.0.0"
  },
  "entities": [
    {
      "name": "Contact",
      "fields": [
        {
          "name": "firstName",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "lastName",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "email",
          "type": "email",
          "required": true,
          "unique": true
        },
        {
          "name": "phone",
          "type": "string",
          "required": false,
          "unique": false
        },
        {
          "name": "company",
          "type": "string",
          "required": false,
          "unique": false
        },
        {
          "name": "status",
          "type": "enum",
          "required": false,
          "unique": false,
          "enumValues": [
            "lead",
            "active",
            "inactive"
          ],
          "default": "lead"
        }
      ],
      "relations": [],
      "ownable": true
    },
    {
      "name": "Invoice",
      "fields": [
        {
          "name": "amount",
          "type": "number",
          "required": true
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "paid",
            "unpaid"
          ],
          "default": "unpaid"
        }
      ],
      "ownable": false
    }
  ],
  "roles": [
    {
      "name": "admin",
      "description": "Administrator with full access",
      "isDefault": false
    },
    {
      "name": "member",
      "description": "Standard user",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "member",
      "entity": "Contact",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "admin",
      "entity": "Contact",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Invoice",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Contacts",
      "route": "/contacts",
      "type": "list",
      "entity": "Contact",
      "access": [
        "member",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "New Contact",
      "route": "/contacts/new",
      "type": "form",
      "entity": "Contact",
      "access": [
        "member",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Dashboard",
      "route": "/dashboard",
      "type": "dashboard",
      "access": [
        "member",
        "admin"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Contacts",
          "entity": "Contact",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Analytics",
      "route": "/analytics",
      "type": "dashboard",
      "access": [
        "admin"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Contacts",
          "entity": "Contact",
          "metric": "count"
        },
        {
          "type": "chart",
          "label": "Contacts by Status",
          "entity": "Contact",
          "metric": "count",
          "field": "status"
        }
      ],
      "requiresPlan": "premium"
    },
    {
      "name": "Invoices",
      "route": "/invoices",
      "type": "list",
      "entity": "Invoice",
      "access": [
        "admin"
      ]
    },
    {
      "name": "New Invoice",
      "route": "/invoices/new",
      "type": "form",
      "entity": "Invoice",
      "access": [
        "admin"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumAnalyticsGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Analytics"
        ],
        "entities": [],
        "features": [
          "analytics"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "contactOwnership",
      "entity": "Contact"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "currency": "usd",
      "interval": "month",
      "isDefault": true,
      "features": []
    },
    {
      "name": "premium",
      "price": 10,
      "currency": "usd",
      "interval": "month",
      "isDefault": false,
      "features": [
        "analytics"
      ]
    }
  ],
  "auth": {
    "strategy": "email_password",
    "providers": [],
    "requireAuth": true
  },
  "assumptions": [
    "The CRM will manage contact information.",
    "Users will have roles such as 'admin' and 'member'.",
    "The 'premium plan' is a subscription-based payment model.",
    "Analytics will be accessible to administrators."
  ]
}
